package com.infosys.carbonfootprint.controller;
import com.infosys.carbonfootprint.dto.*; import com.infosys.carbonfootprint.response.ApiResponse; import com.infosys.carbonfootprint.security.UserDetailsImpl; import com.infosys.carbonfootprint.service.GoalService; import org.springframework.web.bind.annotation.*; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.security.core.annotation.AuthenticationPrincipal; import jakarta.validation.Valid; import java.util.*;
@RestController @RequestMapping("/api/v1/user/goals") @PreAuthorize("hasRole('USER')") public class GoalController { private final GoalService service; public GoalController(GoalService service){this.service=service;} @GetMapping("/current") public ApiResponse<GoalDto> current(@AuthenticationPrincipal UserDetailsImpl u){return ApiResponse.success("Current goal fetched",service.current(u.getId()));} @PostMapping public ApiResponse<GoalDto> save(@Valid @RequestBody GoalRequest r,@AuthenticationPrincipal UserDetailsImpl u){return ApiResponse.success("Goal saved",service.save(u.getId(),r));} @PutMapping("/{id}") public ApiResponse<GoalDto> update(@PathVariable Long id,@Valid @RequestBody GoalRequest r,@AuthenticationPrincipal UserDetailsImpl u){return ApiResponse.success("Goal updated",service.update(u.getId(),id,r));} @GetMapping("/history") public ApiResponse<List<GoalDto>> history(@AuthenticationPrincipal UserDetailsImpl u){return ApiResponse.success("Goal history fetched",service.history(u.getId()));} }